            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                new_path = path + [(nr, nc)]
                heapq.heappush(priority_queue, (heuristic((nr, nc), goal), len(new_path), (nr, nc), new_path))

    return []

