def solve(n, edges, s, t):
    if s == t:
        return 0

    # Initialize distance matrix
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    # Set distance to self to 0
    for i in range(n):
        dist[i][i] = 0

    # Fill in direct edges
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    # - algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] != INF and dist[k][j] != INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # Check if t is reachable from s
    if dist[s][t] == INF:
        return -1
    else:
        return dist[s][t]
